	}
	if offset > len(plain) {
		offset = len(plain)
	}
	end := min(len(plain), offset+width)
	sliced := string(plain[offset:end])
	return padToWidth(sliced, width)
}

func (m *model) scrollLogHorizontally(delta int) {
